parameters.text:
=Write a personalized cold email for this lead.

## Lead Information:
- Name: {{ $json.lead_name }}
- Email: {{ $json.lead_email }}
- Company: {{ $json.company_name }}
- Role: {{ $json.lead_role }}

## Company Research:
{{ $json.company_research }}

## Rules:
1. Subject line must be under 50 characters and curiosity-driven (no spam words like FREE, GUARANTEED, ACT NOW)
2. Email body must be under 150 words
3. First line must reference something specific about their company from the research (not generic)
4. Clearly state what value you offer in one sentence
5. End with a low-friction CTA (question, not a demand)
6. No attachments, no links in the first email
7. Professional but conversational tone, not salesy

Respond ONLY with a valid JSON object (no markdown, no backticks):
{
  "subject": "<subject line>",
  "body": "<full email body with line breaks as \n>",
  "personalization_hook": "<the specific research detail you used>"
}

parameters.jsCode:
const raw = $input.first().json.output || $input.first().json.text || '';
const leadData = $('Prep for Email Writer').first().json;

try {
  let jsonStr = raw;
  const codeBlockMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) jsonStr = codeBlockMatch[1];

  const startIdx = jsonStr.indexOf('{');
  const endIdx = jsonStr.lastIndexOf('}');
  if (startIdx !== -1 && endIdx !== -1) {
    jsonStr = jsonStr.substring(startIdx, endIdx + 1);
  }

  const email = JSON.parse(jsonStr);

  if (!email.subject || !email.body) {
    throw new Error('Missing subject or body in AI response');
  }

  return [{
    json: {
      parseSuccess: true,
      lead_name: leadData.lead_name,
      lead_email: leadData.lead_email,
      company_name: leadData.company_name,
      lead_role: leadData.lead_role,
      subject: email.subject,
      body: email.body,
      personalization_hook: email.personalization_hook || '',
      row_number: leadData.row_number,
      timestamp: new Date().toISOString()
    }
  }];
} catch (e) {
  return [{
    json: {
      parseSuccess: false,
      lead_name: leadData.lead_name,
      lead_email: leadData.lead_email,
      company_name: leadData.company_name,
      error: e.message,
      row_number: leadData.row_number,
      timestamp: new Date().toISOString()
    }
  }];
}
